'use strict';
// Parse a compact duration string such as "1h30m", "45s" or "2d4h" into
// milliseconds, and render milliseconds back into that canonical form.
const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };
const ORDER = Object.keys(UNITS);

function parseDuration(input) {
  if (typeof input !== 'string' || input === '') {
    throw new RangeError(`invalid duration: ${JSON.stringify(input)}`);
  }
  const group = /(\d+)([dhms])/y;
  let total = 0;
  let previous = -1;
  for (let pos = 0; pos < input.length; ) {
    group.lastIndex = pos;
    const match = group.exec(input);
    if (!match) {
      throw new RangeError(`invalid duration at index ${pos}: ${JSON.stringify(input)}`);
    }
    const rank = ORDER.indexOf(match[2]);
    if (rank <= previous) {
      throw new RangeError(`invalid unit order in ${JSON.stringify(input)}`);
    }
    previous = rank;
    total += Number(match[1]) * UNITS[match[2]];
    pos = group.lastIndex;
  }
  return total;
}

function formatDuration(ms) {
  const parts = [];
  for (const [unit, size] of Object.entries(UNITS)) {
    const n = Math.floor(ms / size);
    if (n > 0) parts.push(`${n}${unit}`);
    ms -= n * size;
  }
  return parts.length > 0 ? parts.join('') : '0s';
}

module.exports = { parseDuration, formatDuration };

